function renderTasksFull() {
    var list = $('tasksFullList'); if (!list) return;

/* PATCH v1.0.13: если главный IIFE не доинициализировался (ошибка в другом
   скрипте/блоке), глобальный вызов renderTasksFull() падает с ReferenceError.
   Безопасный fallback-stub ДО объявления реальной функции: function-объявление
   поднимается хостингом и перетирает stub при нормальной инициализации. */
if (typeof window.renderTasksFull !== 'function') {
    window.renderTasksFull = function () {
        try {
            var list = document.getElementById('tasksFullList');
            if (!list) return;
            if (!list.innerHTML || /Загрузка|Подождите/.test(list.innerHTML)) {
                list.innerHTML = '<div class="dict-empty">⚠ Данные ещё не загружены — обновите страницу (F5).</div>';
            }
        } catch (e) { console.error('[renderTasksFull fallback]', e); }
    };
}

window.__trkRenderTasksFull = renderTasksFull;
/* PATCH v1.0.13: алиас в глобальном scope — обработчики, добавленные другими
   патчами/плагинами вне IIFE (например клик по вкладке «Задачи»), вызывают
   renderTasksFull() напрямую; без алиаса это ReferenceError. */
window.renderTasksFull = function () {
    if (typeof renderTasksFull === 'function') return renderTasksFull();
};
